import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.D31cdF9L.js";import"./chunks/assets.DM0yF35s.js";var i=JSON.parse(`{"title":"Project Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}`),a={name:`guide/settings.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="project-settings" tabindex="-1">Project Settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to “Project Settings”">​</a></h1><p>GraphScribe&#39;s options live under <strong>Project Settings → Plugins → GraphScribe</strong>.</p><p><img src="/GraphScribe-Documentation/img/project-settings.png" alt="The GraphScribe Project Settings section" width="1179" height="867"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Default Format</strong></td><td>Which format is pre-selected when you open the export dialogs. Picking a format in a dialog updates this.</td><td>Markdown</td></tr><tr><td><strong>Mermaid Warn Node Count</strong></td><td>Warns you in the export dialog when a Mermaid diagram has more than this many nodes (large diagrams get hard to read)</td><td>250</td></tr><tr><td><strong>Property Dump Mode</strong></td><td>How the reflected CDO / DataAsset property dump is collected (see below)</td><td>Modified Only</td></tr><tr><td><strong>Default Save Directory</strong></td><td>Where exported files are written by default (relative to the project directory)</td><td><code>Saved/GraphScribe</code></td></tr><tr><td><strong>Open Folder After Save</strong></td><td>Whether GraphScribe opens the output folder in your file explorer after each export</td><td>Off</td></tr></tbody></table><h2 id="property-dump-mode" tabindex="-1">Property Dump Mode <a class="header-anchor" href="#property-dump-mode" aria-label="Permalink to “Property Dump Mode”">​</a></h2><p>Every export includes a reflected property dump. The actual property defaults stored on the asset (DataAsset instance or Blueprint CDO). These rows appear in the Variables sections and drive the <code>cls:</code> class-reference linkage. The mode controls how much inherited content that dump contains:</p><ul><li><strong>Modified Only (default)</strong>, properties declared on the asset&#39;s own class <strong>plus</strong> inherited properties whose value differs from the direct parent class defaults (the editor&#39;s definition of &quot;modified&quot;). Containers are compared element-wise and instanced subobjects deeply, so exports show what this class actually changed. Untouched inherited <code>TSubclassOf</code> / <code>TSoftClassPtr</code> references produce no <code>cls:</code> <code>uses</code> edges.</li><li><strong>Full</strong>, every <code>Edit</code> / <code>BlueprintVisible</code> property, including inherited engine properties.</li><li><strong>Blueprint Only</strong>, only properties declared on the asset&#39;s own class (no inherited properties at all).</li></ul><p>The chosen mode is stamped in JSON and Graphify output as the optional <code>dumpMode</code> root field (<code>full</code> / <code>modifiedOnly</code> / <code>blueprintOnly</code>), so consumers can tell why a dump is sparse. See <a href="/GraphScribe-Documentation/reference/schema.html">Schema &amp; Stability</a>.</p><h2 id="what-the-other-settings-mean-in-practice" tabindex="-1">What the other settings mean in practice <a class="header-anchor" href="#what-the-other-settings-mean-in-practice" aria-label="Permalink to “What the other settings mean in practice”">​</a></h2><ul><li><strong>Default Format</strong>, pick Markdown if you mostly write docs, or Graphify if you mostly build AI graphs. You can always switch formats in the dialog, so this is just a convenience.</li><li><strong>Mermaid Warn Node Count</strong>, Mermaid is great, but a flowchart with hundreds of nodes is hard to read. If a diagram exceeds this count, the export dialog shows a warning suggesting Markdown, so you know to narrow the scope.</li><li><strong>Default Save Directory</strong>, set this once to a stable location (for example <code>Documentation/GraphScribe</code> inside your project) so exports always land in the same place. That makes it easy to diff them in git or feed them to tooling. The batch export dialog pre-fills its Output directory from this value.</li><li><strong>Open Folder After Save</strong>, turn this off if you export frequently and find the file explorer popping up annoying.</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to “Tips”">​</a></h2><ul><li>Keep the <strong>Default Save Directory</strong> inside the repo if you want exported docs to show up in pull requests, that&#39;s the main way teams review Blueprint changes.</li><li>If you work with AI agents, point them at the save directory once, then re-run folder exports as your project changes. The Graphify IDs stay stable, so the graph stays useful.</li></ul>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};